/**
 * External function `local_nexusai_quiz_study_plan_dismiss`.
 *
 * SP-13 (#323): dismisses a specific topic from the student's own Study
 * Plan without deleting the underlying history (quiz_errors/unanswered_questions
 * stay intact for the teacher). Operates on the real row IDs
 * (`quiz_error_ids`/`gap_question_ids`, returned by `quiz_study_plan`) — the
 * "topic" text is generated by the LLM on every call, it's not a stable key.
 *
 * Same pattern as `gaps_archive.php`, but:
 *   - capability `local/nexusai:use` (not `:manage`) — it's the student's
 *     own view, not a teacher tool.
 *   - `userid` always from `$USER->id`, never from the client.
 *
 * @package    local_nexusai
 * @copyright  2026 NexusAI Team — UCC
 * @license    https://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

namespace local_nexusai\external;

defined('MOODLE_INTERNAL') || die();
require_once($GLOBALS['CFG']->libdir . '/externallib.php');

/**
 * SP-13 (#323): dismisses a specific topic from the student's own Study Plan without deleting
 * the underlying history (quiz_errors/unanswered_questions stay intact for the teacher).
 */
class quiz_study_plan_dismiss extends \external_api {
    /**
     * Parameters for execute().
     *
     * @return \external_function_parameters
     */
    public static function execute_parameters(): \external_function_parameters {
        return new \external_function_parameters([
            'courseid'       => new \external_value(PARAM_INT, 'Course ID', VALUE_REQUIRED),
            'quizerrorids'   => new \external_multiple_structure(
                new \external_value(PARAM_ALPHANUMEXT, 'UUID of a quiz_errors row'),
                'Quiz error IDs to dismiss',
                VALUE_DEFAULT,
                []
            ),
            'gapquestionids' => new \external_multiple_structure(
                new \external_value(PARAM_ALPHANUMEXT, 'UUID of an unanswered_questions row'),
                'Unanswered question IDs to dismiss',
                VALUE_DEFAULT,
                []
            ),
        ]);
    }

    /**
     * Return value for execute().
     *
     * @return \external_single_structure
     */
    public static function execute_returns(): \external_single_structure {
        return new \external_single_structure([
            'affected' => new \external_value(PARAM_INT, 'Number of rows updated'),
        ]);
    }

    /**
     * SP-13 (#323): dismisses a specific topic from the student's own Study Plan without
     * deleting the underlying history (quiz_errors/unanswered_questions stay intact for the
     * teacher).
     *
     * @param int $courseid Course ID
     * @param array $quizerrorids Quiz error IDs to dismiss
     * @param array $gapquestionids Unanswered question IDs to dismiss
     * @return array
     */
    public static function execute(int $courseid, array $quizerrorids = [], array $gapquestionids = []): array {
        global $USER;

        $params = self::validate_parameters(self::execute_parameters(), [
            'courseid'       => $courseid,
            'quizerrorids'   => $quizerrorids,
            'gapquestionids' => $gapquestionids,
        ]);

        $context = \context_course::instance($params['courseid']);
        self::validate_context($context);
        require_capability('local/nexusai:use', $context);

        if (empty($params['quizerrorids']) && empty($params['gapquestionids'])) {
            throw new \invalid_parameter_exception('At least one id must be provided');
        }

        $client   = new backend_client();
        $response = $client->dismiss_study_plan_topic(
            (int) $params['courseid'],
            (int) $USER->id,
            array_map('strval', $params['quizerrorids']),
            array_map('strval', $params['gapquestionids'])
        );

        return [
            'affected' => (int) ($response['affected'] ?? 0),
        ];
    }
}
